content.content:
"""Build one .ass subtitle file holding captions + animated text pops.

Captions: transcript words (source time) -> mapped through the cut list -> grouped into 1-3 word
chunks -> each chunk pops in, the currently spoken word is highlighted (karaoke style).
Text pops: EDL `text` events ("BRUH", "-1 DIAMOND", "3 HOURS LATER") with pop / shake / slide anims.

libass renders both in the final ffmpeg pass; fonts come from the Editing Pack (copied into work/fonts).
"""
from __future__ import annotations

import json
import re
from pathlib import Path

from .edl import Span, resolve_time, src_to_out


def ass_color(hex_rgb: str, alpha: int = 0) -> str:
    h = hex_rgb.lstrip("#")
    r, g, b = h[0:2], h[2:4], h[4:6]
    return f"&H{alpha:02X}{b}{g}{r}".upper()


def ts(t: float) -> str:
    t = max(0.0, t)
    h, rem = divmod(t, 3600)
    m, s = divmod(rem, 60)
    return f"{int(h)}:{int(m):02d}:{s:05.2f}"


def esc(text: str) -> str:
    return text.replace("\\", "\\\\").replace("{", "(").replace("}", ")").replace("\n", "\\N")


def header(w: int, h: int, cap: dict, text_styles: dict, mode_caps: dict | None = None) -> str:
    styles = [style_line("Caption", cap["font"], cap["size"], cap["primary"], cap["outline"],
                         cap["outline_px"], cap.get("shadow_px", 0))]
    for name, mc in (mode_caps or {}).items():
        styles.append(style_line(f"Cap_{name}", mc["font"], mc["size"], mc["primary"], mc["outline"],
                                 mc["outline_px"], mc.get("shadow_px", 0)))
    styles.append(style_line("Watermark", "Minecraft", int(h * 0.026), "#FFFFFF", "#000000", 2, 0))
    for name, st in text_styles.items():
        styles.append(style_line(f"T_{name}", st["font"], st["size"], st["color"], st["outline"],
                                 st.get("outline_px", 6), st.get("shadow_px", 0)))
    return (
        "[Script Info]\nScriptType: v4.00+\nWrapStyle: 2\nScaledBorderAndShadow: yes\n"
        f"PlayResX: {w}\nPlayResY: {h}\nYCbCr Matrix: TV.709\n\n"
        "[V4+ Styles]\n"
        "Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, "
        "Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, "
        "MarginR, MarginV, Encoding\n" + "\n".join(styles) +
        "\n\n[Events]\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n"
    )


def style_line(name, font, size, color, outline, outline_px, shadow_px) -> str:
    return (f"Style: {name},{font},{size},{ass_color(color)},{ass_color(color)},{ass_color(outline)},"
            f"{ass_color('#000000', 0x60)},0,0,0,0,100,100,1,0,1,{outline_px},{shadow_px},5,40,40,40,1")


# ------------------------------------------------------------------ captions
def chunk_words(words: list[dict], cap: dict) -> list[list[dict]]:
    chunks, cur = [], []
    for w in words:
        text = w["word"].strip()
        if not text:
            continue
        gap = (w["start"] - cur[-1]["end"]) if cur else 0
        chars = sum(len(x["word"].strip()) + 1 for x in cur) + len(text)
        if cur and (len(cur) >= cap["max_words"] or chars > cap["max_chars"] or gap > cap["gap_break_s"]):
            chunks.append(cur)
            cur = []
        cur.append({**w, "word": text})
        if re.search(r"[.!?]$", text):
            chunks.append(cur)
            cur = []
    if cur:
        chunks.append(cur)
    return chunks


def caption_events(words_src: list[dict], spans: list[Span], cap: dict, w: int, h: int,
                   emphasis: set[str], skip_ranges: list[tuple[float, float]],
                   seg_modes: list[str] | None = None, mode_caps: dict | None = None) -> list[str]:
    # map each word into output time; drop words in removed footage
    words = []
    for wd in words_src:
        # clamp each word to the shot it starts in: ASR word ends often bleed into the silence that
        # was cut, which would otherwise stretch a caption across a cutaway
        # every span that shows this footage gets the caption (cold opens repeat footage)
        for sp in (s for s in spans if s.src_to_out(wd["start"]) is not None):
            a = sp.src_to_out(wd["start"])
            b = sp.src_to_out(wd["end"])
            b = min(b if b is not None else sp.out_end, sp.out_end)
            if b <= a or any(s <= a < e for s, e in skip_ranges):
                continue
            mode = seg_modes[sp.seg_index] if seg_modes else None
            words.append({"word": wd["word"], "start": a, "end": b, "mode": mode})
    words.sort(key=lambda w: w["start"])
    out = []
    # chunk per run of the same mode, so a caption never straddles a mood switch
    runs: list[list[dict]] = []
    for wd in words:
        if runs and runs[-1][-1]["mode"] == wd["mode"]:
            runs[-1].append(wd)
        else:
            runs.append([wd])
    chunks = [c for run in runs for c in chunk_words(run, (mode_caps or {}).get(run[0]["mode"], cap))]
    for chunk in chunks:
        mname = chunk[0]["mode"]
        c = (mode_caps or {}).get(mname, cap)
        style_name = f"Cap_{mname}" if mode_caps and mname in mode_caps else "Caption"
        x, y = int(w * 0.5), int(h * c["y"])
        hi, emph, prim = ass_color(c["highlight"]), ass_color(c["emphasis"]), ass_color(c["primary"])
        c_start, c_end = chunk[0]["start"], chunk[-1]["end"] + 0.08
        for i, wd in enumerate(chunk):
            seg_start = c_start if i == 0 else wd["start"]
            seg_end = chunk[i + 1]["start"] if i + 1 < len(chunk) else c_end
            parts = []
            for j, other in enumerate(chunk):
                txt = other["word"].upper() if c.get("uppercase") else other["word"]
                key = re.sub(r"[^a-z0-9']", "", other["word"].lower())
                color = emph if key in emphasis else (hi if j == i else prim)
                parts.append(f"{{\\c{color}}}{esc(txt)}")
            anim = ""
            if i == 0:  # pop the chunk in once
                p = c.get("pop_ms", 90)
                anim = f"\\fscx70\\fscy70\\t(0,{p},\\fscx108\\fscy108)\\t({p},{p + 60},\\fscx100\\fscy100)"
            out.append(f"Dialogue: 1,{ts(seg_start)},{ts(seg_end)},{style_name},,0,0,0,,{{\\an5\\pos({x},{y}){anim}}}"
                       + " ".join(parts))
    return out


# ------------------------------------------------------------------ text pops
def text_events(texts: list[dict], spans: list[Span], styles: dict, w: int, h: int, warnings: list[str],
                mode_style_at=None) -> list[str]:
    out = []
    for i, ev in enumerate(texts):
        at = resolve_time(ev, spans, warnings, f"text[{i}] {ev.get('text')!r}")
        if at is None:
            continue
        # no explicit style -> the current mode's text style (sad = retro, angry = danger, ...)
        st_name = ev.get("style") or (mode_style_at(at) if mode_style_at else None) or "impact"
        st = styles.get(st_name, styles["impact"])
        dur = ev.get("dur", 1.2)
        x, y = int(w * ev.get("x", 0.5)), int(h * ev.get("y", 0.4))
        rot = ev.get("rotate", 0)
        size = ev.get("size")
        tags = [f"\\an5\\pos({x},{y})"]
        if rot:
            tags.append(f"\\frz{rot}")
        if size:
            tags.append(f"\\fs{size}")
        if ev.get("color"):
            tags.append(f"\\c{ass_color(ev['color'])}")
        anim = ev.get("anim", st.get("anim", "pop"))
        if anim == "pop":
            tags.append("\\fscx0\\fscy0\\t(0,110,\\fscx118\\fscy118)\\t(110,190,\\fscx100\\fscy100)")
        elif anim == "slide":
            tags[0] = f"\\an5\\move({x - int(w * 0.25)},{y},{x},{y},0,160)"
        elif anim == "shake":
            # libass has no random; jitter via a few quick \move segments is overkill - use rotation wobble
            tags.append("\\fscx0\\fscy0\\t(0,90,\\fscx115\\fscy115)\\t(90,150,\\frz-6\\fscx100\\fscy100)"
                        "\\t(150,220,\\frz5)\\t(220,290,\\frz-3)\\t(290,360,\\frz0)")
        tags.append(f"\\fad(0,{int(ev.get('fade_out_ms', 120))})")
        out.append(f"Dialogue: 5,{ts(at)},{ts(at + dur)},T_{st_name},,0,0,0,,{{{''.join(tags)}}}{esc(ev['text'])}")
    return out


def build_ass(edl: dict, spans: list[Span], style: dict, transcript_path: Path | None,
              dest: Path, warnings: list[str], modes: dict | None = None, default_mode: str = "funny",
              game_area: tuple[float, float] | None = None) -> bool:
    w, h = style["output"]["width"], style["output"]["height"]
    cap = {**style["captions"], **edl.get("captions", {}).get("style", {})}
    if game_area:                       # stacked facecam short: captions in the gameplay area
        cap["y"] = game_area[0] + game_area[1] * 0.55   # lower gameplay area, above the Shorts UI
    scale = style.get("text_scale", 1.0)
    text_styles = {k: {**v, "size": int(v["size"] * scale)} for k, v in style["text_styles"].items()}
    seg_modes = [sg.get("mode") or default_mode for sg in edl["segments"]]
    mode_caps = {}
    for m in sorted(set(seg_modes)):
        if modes and m in modes:
            mc = {**cap, **modes[m].get("captions", {})}
            if "size" in modes[m].get("captions", {}):        # mode sizes are authored for 16:9
                mc["size"] = int(mc["size"] * cap["size"] / style["_base_caption_size"]) \
                    if style.get("_base_caption_size") else mc["size"]
            if game_area:
                mc["y"] = cap["y"]
            mode_caps[m] = mc

    def mode_at(t: float) -> str:
        sp = next((x for x in spans if x.out_start <= t < x.out_end + 1e-6), None)
        return seg_modes[sp.seg_index] if sp else default_mode

    def mode_style_at(t: float) -> str | None:
        m = mode_at(t)
        return (modes or {}).get(m, {}).get("text_style")
    lines = []
    cap_cfg = edl.get("captions", {})
    if cap_cfg.get("enabled", True) and transcript_path and transcript_path.exists():
        tr = json.loads(transcript_path.read_text(encoding="utf-8"))
        words = [wd for s in tr["segments"] for wd in s.get("words", [])]
        emphasis = {re.sub(r"[^a-z0-9']", "", e.lower()) for e in cap_cfg.get("emphasis_words", [])}
        skips = []
        for i, r in enumerate(cap_cfg.get("hide", [])):   # hide captions during e.g. meme cutaways
            a = resolve_time(r, spans, warnings, f"captions.hide[{i}]")
            if a is not None:
                skips.append((a, a + r.get("dur", 1.0)))
        lines += caption_events(words, spans, cap, w, h, emphasis, skips, seg_modes, mode_caps)
    texts = list(edl.get("text", []))
    # mode headers (POV:) - shown at the start of every run of that mode
    prev = None
    for sp, m in zip(spans, seg_modes):
        hdr = (modes or {}).get(m, {}).get("header")
        sg = edl["segments"][sp.seg_index]
        if hdr and m != prev:
            label = f"{hdr} {sg.get('header_text', '')}".strip()
            texts.append({"text": label, "at": sp.out_start, "dur": min(2.5, sp.out_end - sp.out_start + 1.5),
                          "style": "impact", "y": 0.12, "size": int(text_styles["impact"]["size"] * 0.6)})
        prev = m
    if game_area:                       # text pops move into the gameplay area; the top hook stays on the cam
        top, height = game_area
        texts = [{**t, "y": top + t.get("y", 0.4) * height} if t.get("y", 0.4) > 0.15 else t for t in texts]
    lines += text_events(texts, spans, text_styles, w, h, warnings, mode_style_at)
    wm = edl.get("watermark")
    if wm and not wm.get("image"):                       # image bugs are composited by render.py
        end = spans[-1].out_end if spans else 0
        lines.append(f"Dialogue: 0,{ts(0)},{ts(end + 5)},Watermark,,0,0,0,,"
                     f"{{\\an9\\pos({w - int(w * 0.025)},{int(h * 0.03)})\\alpha&H{int(255 * (1 - wm.get('opacity', 0.55))):02X}&}}"
                     f"{esc(wm.get('text', ''))}")
    if not lines:
        return False
    dest.write_text(header(w, h, cap, text_styles, mode_caps) + "\n".join(lines) + "\n", encoding="utf-8")
    return True
"""Edit Decision List: the single contract between the planner (Claude) and the renderer.

See docs/EDL.md for the full spec. Key ideas:
  * `segments` are the main timeline, played back to back. Output time is cumulative.
  * Everything else (overlays, sfx, music, text, bleeps) is anchored either in OUTPUT time (`at`)
    or in SOURCE time (`src_at`, seconds into the raw gameplay recording). The planner reads the
    transcript in source time, so `src_at` is the natural anchor; the compiler maps it through the cut list.
  * An event whose `src_at` falls inside footage that was cut away is dropped with a warning.
"""
from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path

SEGMENT_TYPES = {"source", "cutaway", "card"}
OVERLAY_TYPES = {"greenscreen", "video", "image", "motion", "transition"}


class EDLError(ValueError):
    pass


@dataclass
class Span:
    """A piece of source footage placed on the output timeline."""
    seg_index: int
    out_start: float
    out_end: float
    src_in: float | None   # None for cutaways/cards (no source mapping)
    speed: float = 1.0
    seg_id: str | None = None

    def src_to_out(self, t: float) -> float | None:
        if self.src_in is None:
            return None
        src_out = self.src_in + (self.out_end - self.out_start) * self.speed
        if self.src_in - 1e-6 <= t <= src_out + 1e-6:
            return self.out_start + (t - self.src_in) / self.speed
        return None


def seg_duration(seg: dict, asset_lookup=None) -> float:
    t = seg.get("type", "source")
    if t == "source":
        d = (seg["out"] - seg["in"]) / seg.get("speed", 1.0)
    elif t == "cutaway":
        if "out" in seg:
            d = seg["out"] - seg.get("in", 0.0)
        else:
            a = asset_lookup(seg["asset"]) if asset_lookup else None
            if not a:
                raise EDLError(f"cutaway {seg.get('id')} needs 'out' (asset duration unknown)")
            d = (a.get("use_out") or a["duration_s"]) - seg.get("in", a.get("use_in") or 0.0)
    elif t == "card":
        if "dur" in seg:
            d = seg["dur"]
        else:                                   # motion-template card: the template's own length
            from .paths import STUDIO
            tj = STUDIO / "motion" / "templates" / seg.get("template", "") / "template.json"
            d = float(json.loads(tj.read_text(encoding="utf-8")).get("duration", 2.0)) if tj.exists() else 2.0
    else:
        raise EDLError(f"unknown segment type {t!r}")
    return d + seg.get("freeze_end", 0.0)


def build_spans(edl: dict, asset_lookup=None) -> list[Span]:
    spans, t = [], 0.0
    for i, seg in enumerate(edl["segments"]):
        d = seg_duration(seg, asset_lookup)
        if d <= 0:
            raise EDLError(f"segment {i} ({seg.get('id')}) has non-positive duration")
        src_in = seg["in"] if seg.get("type", "source") == "source" else None
        live = d - seg.get("freeze_end", 0.0)
        spans.append(Span(i, t, t + live, src_in, seg.get("speed", 1.0), seg.get("id")))
        t += d
    return spans


def total_duration(edl: dict, asset_lookup=None) -> float:
    return sum(seg_duration(s, asset_lookup) for s in edl["segments"])


def src_to_out(spans: list[Span], t: float) -> float | None:
    for sp in spans:
        o = sp.src_to_out(t)
        if o is not None:
            return o
    return None


def resolve_time(ev: dict, spans: list[Span], warnings: list[str], label: str) -> float | None:
    if "seg" in ev:
        # segment-anchored: unambiguous even when the same footage appears twice (cold opens),
        # and it travels with the segment when shorts are cut from the main edit
        sp = next((x for x in spans if x.seg_id == ev["seg"]), None)
        if sp is None:
            warnings.append(f"{label}: segment {ev['seg']!r} not in this edit - dropped")
            return None
        if "rel" in ev:
            return sp.out_start + float(ev["rel"])
        if "src_at" in ev and sp.src_in is not None:
            o = sp.src_to_out(float(ev["src_at"]))
            if o is None:
                warnings.append(f"{label}: src_at={ev['src_at']} outside segment {ev['seg']!r} - dropped")
            return o
        return sp.out_start
    if "at" in ev:
        return float(ev["at"])
    if "src_at" in ev:
        o = src_to_out(spans, float(ev["src_at"]))
        if o is None:
            warnings.append(f"{label}: src_at={ev['src_at']} is in removed footage - dropped")
        return o
    raise EDLError(f"{label}: needs 'at' (output s) or 'src_at' (source s)")


def load(path: Path) -> dict:
    edl = json.loads(Path(path).read_text(encoding="utf-8"))
    validate(edl)
    return edl


def validate(edl: dict) -> None:
    if not edl.get("segments"):
        raise EDLError("EDL has no segments")
    for i, s in enumerate(edl["segments"]):
        t = s.get("type", "source")
        if t not in SEGMENT_TYPES:
            raise EDLError(f"segment {i}: type {t!r} not in {SEGMENT_TYPES}")
        if t == "source" and not (0 <= s["in"] < s["out"]):
            raise EDLError(f"segment {i}: need 0 <= in < out")
        if t == "cutaway" and "asset" not in s and "file" not in s:
            raise EDLError(f"segment {i}: cutaway needs 'asset' or 'file'")
        if t == "card" and not any(k in s for k in ("composition", "file", "motion", "template")):
            raise EDLError(f"segment {i}: card needs 'composition' or 'file'")
    for i, o in enumerate(edl.get("overlays", [])):
        if o.get("type") not in OVERLAY_TYPES:
            raise EDLError(f"overlay {i}: type {o.get('type')!r} not in {OVERLAY_TYPES}")


def collect_asset_ids(edl: dict) -> list[tuple[str, float | None]]:
    """(asset_id, approx time) for usage tracking."""
    out = []
    for s in edl["segments"]:
        if s.get("asset"):
            out.append((s["asset"], None))
    for group in (edl.get("overlays", []), edl.get("audio", {}).get("sfx", []), edl.get("audio", {}).get("music", [])):
        for e in group:
            if e.get("asset"):
                out.append((e["asset"], e.get("at", e.get("src_at"))))
    return out
"""Deterministic first pass: transcript + signals -> edit.json with dead air removed.

    mcs scaffold ep01 [--max-gap 0.6] [--pad 0.15] [--keep-action 1.2] [--music <asset-id>]

Keeps every spoken word (padded), keeps game/voice peaks with some context, cuts gaps longer than
--max-gap. The planner then layers zooms, SFX, memes, captions emphasis etc. on top of this.
"""
from __future__ import annotations

import json

from . import assets as A
from .paths import project_dir


def keep_ranges(words: list[dict], events: list[dict], dur: float, pad: float, max_gap: float,
                keep_action: float, min_len: float = 0.8) -> list[list[float]]:
    rs = [[max(0, w["start"] - pad), min(dur, w["end"] + pad + 0.2)] for w in words]   # ASR ends early: generous tail
    rs += [[max(0, e["t"] - keep_action), min(dur, e["t"] + keep_action)] for e in events]
    rs.sort()
    merged: list[list[float]] = []
    for a, b in rs:
        if merged and a - merged[-1][1] <= max_gap:
            merged[-1][1] = max(merged[-1][1], b)
        else:
            merged.append([a, b])
    return [[round(a, 3), round(b, 3)] for a, b in merged if b - a >= min_len]


def scaffold(slug: str, max_gap: float = 0.6, pad: float = 0.18, keep_action: float = 1.2,
             music: str | None = None, force: bool = False) -> None:
    proj = project_dir(slug)
    dest = proj / "edit.json"
    if dest.exists() and not force:
        raise SystemExit("edit.json exists - pass --force to overwrite (it will be backed up)")
    if dest.exists():
        dest.replace(proj / "edit.backup.json")
    pj = json.loads((proj / "project.json").read_text(encoding="utf-8"))
    tr_p, sig_p = proj / "work" / "transcript.json", proj / "work" / "signals.json"
    words = []
    if tr_p.exists():
        tr = json.loads(tr_p.read_text(encoding="utf-8"))
        words = [w for s in tr["segments"] for w in s["words"]]
    sig = json.loads(sig_p.read_text(encoding="utf-8")) if sig_p.exists() else {}
    events = sig.get("voice_peaks", []) + sig.get("game_peaks", [])
    dur = pj["duration_s"]
    ranges = keep_ranges(words, events, dur, pad, max_gap, keep_action) if (words or events) else [[0, dur]]
    segs = [{"id": f"s{i + 1:03d}", "type": "source", "in": a, "out": b} for i, (a, b) in enumerate(ranges)]
    kept = sum(b - a for a, b in ranges)

    if not music:
        pick = A.find(A.Query(categories=["music"], moments=["exploring", "building"], roles=["music_bed"],
                              max_risk="low", max_energy=3, project=slug, limit=1))
        music = pick[0]["id"] if pick else None
    edl = {
        "version": 1,
        "project": slug,
        "title": pj.get("title", slug),
        "segments": segs,
        "overlays": [],
        "text": [],
        "audio": {"sfx": [], "bleeps": [],
                  "music": [{"asset": music, "at": 0, "fade_in": 1.0, "fade_out": 2.0, "duck": True}] if music else []},
        "captions": {"enabled": True, "emphasis_words": [], "hide": []},
    }
    dest.write_text(json.dumps(edl, indent=2), encoding="utf-8")
    print(f"[scaffold] {len(segs)} segments, kept {kept:.0f}s of {dur:.0f}s ({100 * kept / max(dur, 1):.0f}%), "
          f"music={music} -> edit.json")

"""Cut 9:16 YouTube Shorts out of a finished landscape edit.

    mcs shorts <slug> [--count 3] [--min 12] [--max 45] [--render] [--preview]

Each short becomes a sibling project  projects/<slug>--short-N/  (format: vertical) that reuses the
main edit's segments and every event anchored to them (SFX, zooms, text, overlays travel along), so a
short inherits the full edit for free. Then it gets short-specific treatment:
  * hook headline pinned at the top for the first seconds (from the main edit's "shorts" hints,
    the project title, or the strongest beat)
  * vertical-safe captions (bigger, higher; YouTube UI covers the bottom ~20 %)
  * stacked facecam layout when a facecam exists
  * the music bed that was playing at that point, re-timed
  * no cold open / intro title / outro CTA - shorts start on the action and end on the payoff

Window choice: score = beat density (SFX, text, zooms, cutaways, overlays) + payoff bonus for a strong
beat in the last third, length within [min, max] seconds, windows never overlap.
Manual override: the main edit.json may contain
  "shorts": [{"from": "<seg id>", "to": "<seg id>", "hook": "HOOK TEXT"}]
"""
from __future__ import annotations

import json
import re
import shutil
from pathlib import Path

from . import assets as A
from .edl import build_spans, resolve_time, seg_duration
from .paths import PROJECTS, project_dir

STRONG = {"death", "panic", "jumpscare", "explosion", "victory", "shock", "fail", "irony"}


def _events_by_seg(edl: dict) -> dict[str, float]:
    """weight of attention-grabbing events per segment id"""
    w: dict[str, float] = {}
    for grp, val in (("text", 1.0), ("overlays", 1.5)):
        for e in edl.get(grp, []):
            if e.get("seg"):
                w[e["seg"]] = w.get(e["seg"], 0) + val
    for e in edl.get("audio", {}).get("sfx", []):
        if e.get("seg"):
            w[e["seg"]] = w.get(e["seg"], 0) + 1.0
    for s in edl["segments"]:
        w[s["id"]] = w.get(s["id"], 0) + 0.6 * len([z for z in s.get("zoom", []) if not z.get("auto")])
        if s.get("type") == "cutaway":
            w[s["id"]] = w.get(s["id"], 0) + 2.0
        if s.get("freeze_end"):
            w[s["id"]] = w.get(s["id"], 0) + 1.5
    return w


def candidate_windows(edl: dict, lo: float, hi: float) -> list[dict]:
    segs = [s for s in edl["segments"] if not s["id"].startswith("cold")]
    lookup = lambda i: A.get(i)  # noqa: E731
    durs = [seg_duration(s, lookup) for s in segs]
    weights = _events_by_seg(edl)
    out = []
    for i in range(len(segs)):
        if segs[i].get("type") == "cutaway":
            continue                                     # never open a short on a meme
        total, score = 0.0, 0.0
        for j in range(i, len(segs)):
            total += durs[j]
            score += weights.get(segs[j]["id"], 0)
            if total > hi:
                break
            if total >= lo and segs[j].get("type") != "cutaway" or (total >= lo and j == len(segs) - 1):
                tail = segs[max(i, j - 2): j + 1]
                payoff = 2.5 if any(s.get("freeze_end") or s.get("mode") in ("sad", "scary", "exciting")
                                    for s in tail) else 0
                density = score / total
                out.append({"from": i, "to": j, "dur": total, "score": density * 10 + payoff + min(total, 35) / 35})
    return sorted(out, key=lambda c: -c["score"])


def pick_windows(edl: dict, count: int, lo: float, hi: float) -> list[dict]:
    segs = [s for s in edl["segments"] if not s["id"].startswith("cold")]
    if edl.get("shorts"):
        ids = [s["id"] for s in segs]
        return [{"from": ids.index(x["from"]), "to": ids.index(x["to"]), "hook": x.get("hook")} for x in edl["shorts"]]
    chosen: list[dict] = []
    for c in candidate_windows(edl, lo, hi):
        if all(c["to"] < k["from"] or c["from"] > k["to"] for k in chosen):
            chosen.append(c)
        if len(chosen) >= count:
            break
    return sorted(chosen, key=lambda c: c["from"])


BORING = re.compile(r"EARLIER|LATER|SPEED|X\d+$|^\+1 ", re.I)
TEASES = {"sad": "THIS DID NOT GO WELL...", "scary": "WAIT FOR THE ENDING...", "exciting": "WATCH TILL THE END...",
          "angry": "HE LOST IT...", "happy": "BEST MOMENT EVER?", "funny": "HOW DID THIS HAPPEN?!"}


def hook_text(edl: dict, segs: list[dict], pj: dict, n: int) -> str:
    """A hook must promise the payoff. First short: the episode title; others: a strong on-screen line
    from inside the window, else a tease matched to how the window ends."""
    title = (pj.get("title") or "").upper()
    if n == 1 and title:
        return title[:34] + ("..." if not title.endswith(("!", "?", "...")) else "")
    ids = {s["id"] for s in segs}
    texts = [t["text"] for t in edl.get("text", []) if t.get("seg") in ids and len(t["text"]) <= 22
             and t.get("style") != "label" and not BORING.search(t["text"])]
    if texts:
        return texts[0]
    end_mode = segs[-1].get("mode") or edl.get("mode", "funny")
    return TEASES.get(end_mode, TEASES["funny"])


def make_short(slug: str, n: int, win: dict, edl: dict, pj: dict) -> str:
    main_segs = [s for s in edl["segments"] if not s["id"].startswith("cold")]
    segs = [dict(s) for s in main_segs[win["from"]: win["to"] + 1]]
    ids = {s["id"] for s in segs}
    keep = lambda e: e.get("seg") in ids or ("src_at" in e and "seg" not in e and "at" not in e)  # noqa: E731
    skip_text = {"label"}                                # intro titles / speed labels stay in the long video
    texts = [dict(t) for t in edl.get("text", []) if keep(t)
             and not (t.get("style") in skip_text and "SPEED" not in t["text"])
             and not re.search(r"EARLIER|LATER", t["text"], re.I)]      # cold-open segues mean nothing in a short
    hook = win.get("hook") or hook_text(edl, segs, pj, n)
    hook_overlay = {"type": "motion", "template": "hook_banner", "vars": {"text": hook}, "seg": segs[0]["id"],
                    "rel": 0.0, "dur": 3.2}
    overlays = [dict(o) for o in edl.get("overlays", []) if keep(o) and o.get("type") != "transition"
                and o.get("template") not in ("title_card", "subscribe", "time_card", "end_screen")]
    overlays.insert(0, hook_overlay)
    for o in overlays:                                    # corner overlays read better centred on a phone
        if o.get("x") is not None and o.get("placement") != "fullscreen":
            o["x"], o["scale"] = 0.5, min(0.32, o.get("scale", 0.45))
    sfx = [dict(e) for e in edl.get("audio", {}).get("sfx", []) if keep(e)
           and not (e.get("rel") is not None and e.get("rel") <= 0 and "rewind" in e.get("asset", ""))]

    # music: whatever bed was playing where the short starts, re-timed into the short
    spans_main = build_spans(edl, lambda i: A.get(i))
    start_out = next(sp.out_start for sp in spans_main if sp.seg_id == segs[0]["id"])
    total = sum(seg_duration(s, lambda i: A.get(i)) for s in segs)
    music = []
    for m in edl.get("audio", {}).get("music", []):
        at = resolve_time(m, spans_main, [], "music") if ("at" in m or "src_at" in m or "seg" in m) else 0.0
        until = m.get("until", 1e9)
        if at is not None and at <= start_out < until:
            music.append({**{k: v for k, v in m.items() if k not in ("at", "until", "src_at", "seg")},
                          "at": 0.0, "until": round(total, 3), "in": round(m.get("in", 0) + start_out - at, 2),
                          "fade_in": 0.2, "fade_out": 0.8})
            break
    if not music and edl.get("audio", {}).get("music"):
        m = edl["audio"]["music"][0]
        music.append({"asset": m["asset"], "at": 0.0, "until": round(total, 3), "fade_in": 0.2, "fade_out": 0.8})

    short = {"version": 1, "project": f"{slug}--short-{n}", "title": hook, "format": "vertical",
             "mode": edl.get("mode", "funny"), "parent": slug, "segments": segs, "overlays": overlays,
             "text": texts, "audio": {"sfx": sfx, "bleeps": [b for b in edl.get("audio", {}).get("bleeps", [])
                                                         if keep(b)], "music": music},
             "captions": {**edl.get("captions", {}), "hide": []}}
    if edl.get("watermark"):
        short["watermark"] = edl["watermark"]
    if edl.get("facecam"):
        short["facecam"] = {**edl["facecam"], "layout": "stack"}

    sslug = f"{slug}--short-{n}"
    dst = PROJECTS / sslug
    (dst / "work").mkdir(parents=True, exist_ok=True)
    src = project_dir(slug)
    spj = dict(pj)
    for k, s in spj.get("sources", {}).items():           # absolutise relative source paths
        if isinstance(s, dict) and s.get("file") and not Path(s["file"]).is_absolute():
            s["file"] = str((src / s["file"]).resolve())
    spj.update({"slug": sslug, "title": hook, "kind": "short", "parent": slug})
    (dst / "project.json").write_text(json.dumps(spj, indent=2), encoding="utf-8")
    for f in ("transcript.json", "transcript.md", "signals.json", "levels.json"):
        if (src / "work" / f).exists():
            shutil.copy2(src / "work" / f, dst / "work" / f)
    (dst / "edit.json").write_text(json.dumps(short, indent=2), encoding="utf-8")
    print(f"[shorts] {sslug}: {len(segs)} segments, {total:.1f}s, hook {hook!r}")
    return sslug


def make_shorts(slug: str, count: int = 3, lo: float = 12, hi: float = 45, render: bool = False,
                preview: bool = False) -> list[str]:
    proj = project_dir(slug)
    edl = json.loads((proj / "edit.json").read_text(encoding="utf-8"))
    pj = json.loads((proj / "project.json").read_text(encoding="utf-8"))
    for old in PROJECTS.glob(f"{slug}--short-*"):
        if (old / "edit.json").exists() and not edl.get("shorts_keep"):
            shutil.rmtree(old / "work" / "full", ignore_errors=True)
    wins = pick_windows(edl, count, lo, hi)
    if not wins:
        print("[shorts] no window fits - try a lower --min")
        return []
    made = [make_short(slug, i + 1, w, edl, pj) for i, w in enumerate(wins)]
    if render:
        from .render import render as do_render
        for s in made:
            do_render(s, preview=preview, record=False)
    return made
