content.content:
1	// MC Studio — single-page UI. No build step; talks to mcstudio/server.py.
2	const $ = (s, el = document) => el.querySelector(s);
3	const $$ = (s, el = document) => [...el.querySelectorAll(s)];
4	const view = $("#view");
5	const player = $("#player");
6	const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
7	const fmt = (t) => { if (t == null || isNaN(t)) return "–"; const m = Math.floor(t / 60), s = (t % 60).toFixed(1).padStart(4, "0"); return `${m}:${s}`; };
8	const fmtSize = (b) => b > 1e9 ? (b / 1e9).toFixed(1) + " GB" : b > 1e6 ? (b / 1e6).toFixed(1) + " MB" : (b / 1e3).toFixed(0) + " KB";
9	const enc = (p) => p.split("/").map(encodeURIComponent).join("/");
10	const packUrl = (p, root = "Editing Pack") => root === "studio" ? `/media/studio/${enc(p)}`
11	  : `/media/lib/${encodeURIComponent(root)}/${enc(p)}`;
12	const thumbUrl = (t) => t.startsWith("brand/") ? `/media/studio/${enc(t)}` : `/media/catalog/${t}`;
13	let MODES = {};
14	
15	async function api(path, opts = {}) {
16	  const r = await fetch(path, { headers: { "Content-Type": "application/json" }, ...opts,
17	    body: opts.body && typeof opts.body !== "string" ? JSON.stringify(opts.body) : opts.body });
18	  if (!r.ok) { let m = r.statusText; try { m = (await r.json()).detail || m; } catch {} throw new Error(m); }
19	  return r.json();
20	}
21	function toast(msg, err = false) {
22	  const t = $("#toast"); t.textContent = msg; t.className = "toast" + (err ? " err" : ""); t.hidden = false;
23	  clearTimeout(toast._t); toast._t = setTimeout(() => (t.hidden = true), 3500);
24	}
25	const store = { get: (k, d) => { try { return JSON.parse(localStorage.getItem(k)) ?? d; } catch { return d; } },
26	                set: (k, v) => { try { localStorage.setItem(k, JSON.stringify(v)); } catch {} } };
27	
28	let TAX = null;
29	let pollers = [];
30	function clearPollers() { pollers.forEach(clearInterval); pollers = []; }
31	
32	// ---------------------------------------------------------------- shell
33	async function boot() {
34	  [TAX, MODES] = await Promise.all([api("/api/taxonomy"), api("/api/modes")]);
35	  refreshSide();
36	  window.addEventListener("hashchange", route);
37	  route();
38	}
39	async function refreshSide() {
40	  try {
41	    const [s, h] = await Promise.all([api("/api/stats"), api("/api/health")]);
42	    $("#sideStats").innerHTML = `<div><b>${s.tagged}</b> tagged assets</div>
43	      <div><b>${s.by_rating.banned || 0}</b> banned · <b>${s.by_risk.high || 0}</b> high-©</div>`;
44	    $("#health").innerHTML = ["ffmpeg", "assets_db", "claude"].map((k) =>
45	      `<div><span class="dot ${h[k] ? "ok" : k === "claude" ? "" : "bad"}"></span>${k === "claude" ? "claude CLI" : k}</div>`).join("");
46	  } catch {}
47	}
48	function route() {
49	  clearPollers();
50	  closeDrawer();
51	  const [, page, arg] = location.hash.split("/");
52	  $$("nav a").forEach((a) => a.classList.toggle("active", a.dataset.nav === (page === "project" ? "projects" : page || "projects")));
53	  ({ library: Library, motion: Motion, new: NewEpisode, jobs: Jobs, brand: Brand, brandlib: BrandLibrary, pipeline: Pipeline, project: () => Project(decodeURIComponent(arg || "")) }[page] || Projects)();
54	}
55	
56	// ---------------------------------------------------------------- library
57	const LIB = store.get("lib", { q: "", category: [], moment: [], rating: ["clean", "mild"], ranked: false, offset: 0 });
58	async function Library() {
59	  view.innerHTML = `
60	    <div class="row"><div><h1>Asset library</h1><p class="sub">Every sound, meme, green screen and graphic in the Editing Pack, tagged for the auto-editor.</p></div></div>
61	    <div class="filters card">
62	      <div class="row">
63	        <input id="q" type="search" placeholder="Search: creeper, sad violin, bruh, diamond…" style="flex:1;min-width:240px" value="${esc(LIB.q)}">
64	        <select id="momentSel"><option value="">+ moment…</option>${Object.entries(TAX.moments).map(([k, v]) => `<option value="${k}" title="${esc(v)}">${k}</option>`).join("")}</select>
65	        <label class="chip ${LIB.ranked ? "on" : ""}" id="ranked" title="Use the planner's scoring (needs a moment or search)">★ Planner ranking</label>
66	        <label class="chip fav-chip ${LIB.favorites ? "on" : ""}" id="favsOnly" title="Only assets you starred (the auto-editor prefers them)">★ Favourites</label>
67	        <select id="rootSel"><option value="">All libraries</option><option value="Editing Pack" ${LIB.root === "Editing Pack" ? "selected" : ""}>Editing Pack</option><option value="Stock Library" ${LIB.root === "Stock Library" ? "selected" : ""}>My Stock Library</option></select>
68	        <button class="btn primary" id="addFootage">＋ Add footage</button>
69	      </div>
70	      <div class="chips" id="cats">${Object.keys(TAX.categories).filter((c) => c !== "reference").map((c) =>
71	        `<span class="chip ${LIB.category.includes(c) ? "on" : ""}" data-c="${c}" title="${esc(TAX.categories[c])}">${c.replace("_", " ")}</span>`).join("")}</div>
72	      <div class="row">
73	        <div class="chips" id="moments">${LIB.moment.map((m) => `<span class="chip on" data-m="${m}">${m} ✕</span>`).join("")}</div>
74	        <span class="spacer"></span>
75	        <div class="chips" id="ratings">${Object.keys(TAX.content_rating).map((r) =>
76	          `<span class="chip ${LIB.rating.includes(r) ? "on" : ""}" data-r="${r}">${r}</span>`).join("")}</div>
77	      </div>
78	    </div>
79	    <div class="row muted" id="count"></div>
80	    <div class="grid" id="grid"></div>
81	    <div class="pager" id="pager"></div>`;
82	  let t;
83	  $("#q").addEventListener("input", (e) => { clearTimeout(t); t = setTimeout(() => { LIB.q = e.target.value; LIB.offset = 0; load(); }, 250); });
84	  $("#momentSel").addEventListener("change", (e) => { if (e.target.value && !LIB.moment.includes(e.target.value)) LIB.moment.push(e.target.value); e.target.value = ""; LIB.offset = 0; Library(); });
85	  $("#moments").addEventListener("click", (e) => { const m = e.target.dataset.m; if (m) { LIB.moment = LIB.moment.filter((x) => x !== m); LIB.offset = 0; Library(); } });
86	  $("#cats").addEventListener("click", (e) => { const c = e.target.dataset.c; if (!c) return; toggle(LIB.category, c); e.target.classList.toggle("on"); LIB.offset = 0; load(); });
87	  $("#ratings").addEventListener("click", (e) => { const r = e.target.dataset.r; if (!r) return; toggle(LIB.rating, r); e.target.classList.toggle("on"); LIB.offset = 0; load(); });
88	  $("#ranked").addEventListener("click", (e) => { LIB.ranked = !LIB.ranked; e.target.classList.toggle("on"); load(); });
89	  $("#favsOnly").addEventListener("click", (e) => { LIB.favorites = !LIB.favorites; e.target.classList.toggle("on"); LIB.offset = 0; load(); });
90	  $("#rootSel").addEventListener("change", (e) => { LIB.root = e.target.value; LIB.offset = 0; load(); });
91	  $("#addFootage").onclick = addFootage;
92	  load();
93	
94	  async function load() {
95	    store.set("lib", LIB);
96	    const p = new URLSearchParams({ q: LIB.q, limit: 60, offset: LIB.offset, ranked: LIB.ranked, root: LIB.root || "", favorites: !!LIB.favorites });
97	    LIB.category.forEach((c) => p.append("category", c));
98	    LIB.moment.forEach((m) => p.append("moment", m));
99	    LIB.rating.forEach((r) => p.append("rating", r));
100	    const res = await api("/api/assets?" + p);
101	    let items = res.items;
102	    if (LIB.ranked) items = items.filter((a) => !LIB.rating.length || LIB.rating.includes(a.content_rating));
103	    $("#count").textContent = `${LIB.ranked ? items.length + " best matches" : res.total + " assets"}`;
104	    $("#grid").innerHTML = items.map(assetCard).join("") || `<div class="empty">No assets match. Loosen the filters.</div>`;
105	    $$("#grid .asset").forEach((el, i) => {
106	      el.addEventListener("click", (e) => { if (e.target.closest(".play, .star")) return; openAsset(items[i].id); $$(".asset.sel").forEach((x) => x.classList.remove("sel")); el.classList.add("sel"); });
107	      const pb = $(".play", el); if (pb) pb.addEventListener("click", () => playAsset(items[i], pb));
108	      $(".star", el).addEventListener("click", async (e) => {
109	        e.stopPropagation();
110	        const a = await toggleFavorite(items[i], !el.classList.contains("fav")); if (!a) return;
111	        if (LIB.favorites && !a.favorite) load();
112	      });
113	    });
114	    const pages = Math.ceil(res.total / 60), cur = LIB.offset / 60;
115	    $("#pager").innerHTML = LIB.ranked || pages <= 1 ? "" :
116	      `<button class="btn small" ${cur === 0 ? "disabled" : ""} id="prev">← Prev</button><span>Page ${cur + 1} / ${pages}</span><button class="btn small" ${cur + 1 >= pages ? "disabled" : ""} id="next">Next →</button>`;
117	    $("#prev")?.addEventListener("click", () => { LIB.offset -= 60; load(); scrollTo(0, 0); });
118	    $("#next")?.addEventListener("click", () => { LIB.offset += 60; load(); scrollTo(0, 0); });
119	  }
120	}
121	async function addFootage() {
122	  const st = await api("/api/library/status");
123	  const m = $("#modal");
124	  m.innerHTML = `<div class="modal-box"><div class="modal-head"><b>Add to your Stock Library</b><span class="spacer"></span><button class="btn small" id="mclose">✕</button></div>
125	    <div class="modal-body" style="padding:16px;display:grid;gap:12px">
126	      <div class="muted">${st.library_assets} assets in your library · ${st.untagged} waiting to be tagged</div>
127	      <label class="field">Folder<select id="lfolder">${st.folders.map((f) => `<option>${esc(f)}</option>`).join("")}</select></label>
128	      <label class="field">Files (video, audio, images)<input id="lfiles" type="file" multiple accept="video/*,audio/*,image/*"></label>
129	      <div class="row"><button class="btn primary" id="lup">Upload &amp; scan</button><span id="lmsg" class="muted"></span></div>
130	      <hr style="border-color:var(--line);width:100%">
131	      <div><b>Tagging</b> <span class="muted">(Claude looks at each clip and files it: subject, mood, moments, where it fits)</span></div>
132	      <textarea rows="3" id="lprompt">${esc(st.tag_prompt)}</textarea>
133	      <div class="row">${st.claude ? `<button class="btn gold" id="ltag">Tag new assets with Claude</button>` : `<button class="btn" id="lcopy">Copy prompt for Claude Code</button>`}</div>
134	    </div></div>`;
135	  m.hidden = false;
136	  $("#mclose").onclick = () => (m.hidden = true);
137	  $("#lup").onclick = async () => {
138	    const files = $("#lfiles").files;
139	    if (!files.length) return toast("Pick some files first", true);
140	    const fd = new FormData(); fd.append("folder", $("#lfolder").value); [...files].forEach((f) => fd.append("files", f));
141	    $("#lmsg").textContent = `Uploading ${files.length} file(s)…`;
142	    const r = await fetch("/api/library/upload", { method: "POST", body: fd });
143	    if (!r.ok) return toast("Upload failed", true);
144	    const j = await r.json(); $("#lmsg").textContent = `Saved ${j.saved.length}. Scanning (see Jobs)…`;
145	  };
146	  $("#lcopy")?.addEventListener("click", () => { navigator.clipboard.writeText($("#lprompt").value); toast("Prompt copied"); });
147	  $("#ltag")?.addEventListener("click", async () => { try { await api("/api/library/tag", { method: "POST" }); toast("Tagging started (see Jobs)"); m.hidden = true; } catch (e) { toast(e.message, true); } });
148	}
149	
150	async function toggleFavorite(a, on) {   // `on` comes from the DOM, so card + drawer never disagree
151	  try {
152	    const r = await api(`/api/assets/${encodeURIComponent(a.id)}/favorite`, { method: "POST", body: { on } });
153	    a.favorite = r.favorite;
154	    markFavorite(r.id, r.favorite);
155	    toast(r.favorite ? "★ Favourited: the auto-editor will prefer it" : "Removed from favourites");
156	    return r;
157	  } catch (e) { toast(e.message, true); }
158	}
159	function markFavorite(id, on) {   // sync every card + the drawer button showing this asset
160	  $$(`.asset[data-id="${CSS.escape(id)}"]`).forEach((el) => {
161	    el.classList.toggle("fav", on);
162	    const s = $(".star", el); s.textContent = on ? "★" : "☆"; s.title = on ? "Unfavourite" : "Favourite";
163	  });
164	  const b = $(`#favBtn[data-id="${CSS.escape(id)}"]`);
165	  if (b) { b.classList.toggle("on", on); b.textContent = on ? "★ Favourited" : "☆ Favourite"; }
166	}
167	function toggle(arr, v) { const i = arr.indexOf(v); i >= 0 ? arr.splice(i, 1) : arr.push(v); }
168	function ratingBadge(r) { return r ? `<span class="badge r-${r}">${r}</span>` : ""; }
169	function assetCard(a) {
170	  const audio = a.kind === "audio";
171	  const thumb = a.thumb ? `style="background-image:url('${thumbUrl(a.thumb)}')"` : "";
172	  const playable = a.kind === "audio" || (a.kind === "video" && a.has_audio);
173	  return `<div class="asset ${a.favorite ? "fav" : ""}" title="${esc(a.id)}" data-id="${esc(a.id)}">
174	    <div class="thumb ${audio ? "audio" : ""}" ${thumb}>
175	      <span class="star" title="${a.favorite ? "Unfavourite" : "Favourite"}">${a.favorite ? "★" : "☆"}</span>
176	      ${audio ? `<span class="wave">${a.category === "music" ? "♫" : "♪"}</span>` : ""}
177	      ${playable ? `<span class="play" title="Play">▶</span>` : ""}
178	      ${a.duration_s ? `<span class="dur">${a.duration_s.toFixed(1)}s</span>` : ""}
179	    </div>
180	    <div class="meta">
181	      <div class="title">${esc(a.title)}</div>
182	      <div class="desc">${esc(a.description || "")}</div>
183	      <div class="badges"><span class="badge">${a.category}</span>${a.tagged ? ratingBadge(a.content_rating) : `<span class="badge" style="color:var(--diamond)">untagged</span>`}
184	        ${a.copyright_risk === "high" ? `<span class="badge k-risk-high">© high</span>` : ""}
185	        ${a.key_mode && a.key_mode !== "none" ? `<span class="badge">${a.key_mode}</span>` : ""}
186	        ${a.score != null ? `<span class="badge" style="color:var(--gold)">★ ${a.score}</span>` : ""}</div>
187	    </div></div>`;
188	}
189	function playAsset(a, btn) {
190	  const url = packUrl(a.path, a.root);
191	  if (!player.paused && player.dataset.id === a.id) { player.pause(); btn.textContent = "▶"; return; }
192	  $$(".play").forEach((b) => (b.textContent = "▶"));
193	  player.src = url; player.dataset.id = a.id;
194	  player.currentTime = 0; player.play().catch(() => toast("Can't play this format in the browser", true));
195	  btn.textContent = "❚❚";
196	  player.onended = () => (btn.textContent = "▶");
197	}
198	function closeDrawer() { const d = $("#drawer"); d.hidden = true; d.innerHTML = ""; }
199	async function openAsset(id) {
200	  const a = await api("/api/assets/" + encodeURIComponent(id));
201	  const d = $("#drawer");
202	  const url = packUrl(a.path, a.root);
203	  const media = a.kind === "video" ? `<video src="${url}" controls preload="metadata"></video>`
204	    : a.kind === "audio" ? `<audio src="${url}" controls style="width:100%"></audio>`
205	    : a.kind === "image" ? `<img class="preview" src="${url}">`
206	    : a.thumb ? `<img class="preview" src="${thumbUrl(a.thumb)}">` : "";
207	  const opt = (list, cur) => list.map((v) => `<option ${v === cur ? "selected" : ""}>${v}</option>`).join("");
208	  d.innerHTML = `<button class="btn small close" id="dclose">✕</button>
209	    <h3>${esc(a.title)}</h3>
210	    <div class="row" style="margin-bottom:10px"><code class="mono">${esc(a.id)}</code><button class="btn small" id="copyId">Copy ID</button>
211	      <button class="btn small fav-btn ${a.favorite ? "on" : ""}" id="favBtn" data-id="${esc(a.id)}" title="Starred assets get a bonus in the auto-editor">${a.favorite ? "★ Favourited" : "☆ Favourite"}</button></div>
212	    ${media}
213	    <p>${esc(a.description || "")}</p>
214	    <div class="chips">${a.moments.map((m) => `<span class="chip on">${m}</span>`).join("")}${a.roles.map((r) => `<span class="chip">${r}</span>`).join("")}</div>
215	    <dl class="kv">
216	      <dt>Category</dt><dd>${a.category} · ${esc(a.subfolder)}</dd>
217	      <dt>Rating</dt><dd>${ratingBadge(a.content_rating)} <span class="badge k-risk-${a.copyright_risk}">© ${a.copyright_risk || "?"}</span></dd>
218	      ${a.quote ? `<dt>Quote</dt><dd>“${esc(a.quote)}”</dd>` : ""}
219	      <dt>Energy / mood</dt><dd>${a.energy ?? "–"} / ${esc(a.mood || "–")}</dd>
220	      <dt>Duration</dt><dd>${a.duration_s ? a.duration_s.toFixed(2) + "s" : "–"} ${a.peak_s != null ? `· hit @ ${a.peak_s}s` : ""} ${a.use_in != null ? `· use ${a.use_in}–${a.use_out}s` : ""}</dd>
221	      ${a.width ? `<dt>Size</dt><dd>${a.width}×${a.height}${a.fps ? " @ " + a.fps : ""}</dd>` : ""}
