// ---------------------------------------------------------------- settings (feature on/off switches)
// One generic renderer for studio/settings.json (global) and projects/<slug>/settings.json (episode overrides).
// The schema comes from /api/settings/schema (mcstudio/settings.py SCHEMA), so a new setting needs no UI code.
let SET_SCHEMA = null;
const setSchema = async (fresh = false) => (SET_SCHEMA = fresh || !SET_SCHEMA ? await api("/api/settings/schema") : SET_SCHEMA);
const APPLIES = {
  plan: ["plan", "Used by the auto-editor when it plans an edit: re-plan (Auto-edit) to see the change."],
  render: ["render", "Applied by the renderer, also to existing edits: just re-render."],
  both: ["plan + render", "The auto-editor stops placing it AND the renderer strips it from existing edits."],
};
const sget = (obj, path) => { const [a, b] = path.split("."); return obj?.[a]?.[b]; };
const shas = (obj, path) => { const [a, b] = path.split("."); return !!obj?.[a] && b in obj[a] && obj[a][b] !== null; };
const sput = (obj, path, v) => { const [a, b] = path.split("."); (obj[a] ||= {})[b] = v; };
const sdel = (obj, path) => { const [a, b] = path.split("."); if (obj[a]) { delete obj[a][b]; if (!Object.keys(obj[a]).length) delete obj[a]; } };
function setFmt(s, v) {
  if (v == null) return "–";
  if (s.type === "bool") return v ? "on" : "off";
  if (s.type === "multi") return v.length ? `${v.length} switched off` : "all on";
  if (s.type === "select") return s.options.find((o) => o.value === v)?.label ?? v;
  return `${v}${s.unit && s.unit !== "×" ? " " + s.unit : s.unit || ""}`;
}
const SET_UI = { q: "", tq: {} };          // search text + per-list chip filters survive re-renders

// o = { project: bool, eff (effective values), inh (inherited/global values), ov (overrides), onSet(path, value|null), onReset(section|null) }
function renderSettings(el, sch, o) {
  const open = store.get("setOpen", {});
  const val = (path) => sget(o.eff, path);
  const greyed = (sec, s) => (sec.master && s.key !== sec.master && !val(`${sec.key}.${sec.master}`))
    || (s.requires && !val(s.requires));
  const control = (s, v, locked) => {
    const p = esc(s.path), dis = locked ? "disabled" : "";
    if (s.type === "bool") return `<label class="switch" title="${v ? "On" : "Off"}"><input type="checkbox" data-bool="${p}" ${v ? "checked" : ""} ${dis}><span></span></label>`;
    if (s.type === "number") return `<div class="row set-num"><input type="range" data-num="${p}" min="${s.min}" max="${s.max}" step="${s.step}" value="${v}" ${dis}><output>${esc(setFmt(s, v))}</output></div>`;
    if (s.type === "select") return `<select data-sel="${p}" ${dis}>${s.options.map((op) => `<option value="${esc(op.value)}" ${op.value === v ? "selected" : ""}>${esc(op.label)}</option>`).join("")}</select>`;
    if (s.type === "multi") {
      const off = new Set(v || []), q = (SET_UI.tq[s.path] || "").toLowerCase();
      const thumbs = s.options.some((op) => op.poster);
      const opts = s.options.filter((op) => !q || (op.value + " " + (op.label || "") + " " + (op.help || "")).toLowerCase().includes(q));
      return `<div class="set-multi">
        <div class="row" style="gap:6px;margin-bottom:6px">${s.options.length > 10 ? `<input type="search" class="sm" data-tq="${p}" placeholder="Filter ${s.options.length}…" value="${esc(SET_UI.tq[s.path] || "")}" style="min-width:160px">` : ""}
          <span class="faint" style="font-size:12px">${s.options.length - off.size}/${s.options.length} on</span><span class="spacer"></span>
          <button class="btn sm" data-allon="${p}" ${dis}>All on</button><button class="btn sm" data-alloff="${p}" ${dis}>All off</button></div>
        <div class="${thumbs ? "tchips" : "chips"}">${opts.map((op) => {
          const on = !off.has(op.value);
          return thumbs
            ? `<div class="tchip ${on ? "on" : ""} ${locked ? "locked" : ""}" data-chip="${p}" data-v="${esc(op.value)}" title="${esc(op.help || op.value)}">
                 <div class="tposter">${op.poster ? `<img src="${op.poster}" loading="lazy" alt="">` : `<span class="faint">no preview</span>`}<span class="tstate">${on ? "ON" : "OFF"}</span></div>
                 <div class="tname">${esc(op.label)}</div></div>`
