        `<button class="btn small ${(k === "inherit" && !has) || (has && (k === "on") === !!shown && k !== "inherit") ? "on" : ""}" data-tri="${esc(path)}" data-v="${k}">${l}</button>`).join("")}</div>`;
    } else if (o.project) {
      ctl = `<div class="seg tri" style="margin-bottom:6px"><button class="btn small ${has ? "" : "on"}" data-inherit="${esc(path)}">Inherit</button><button class="btn small ${has ? "on" : ""}" data-custom="${esc(path)}">Custom</button></div>
        ${control(s, shown, !has)}${has ? "" : `<div class="faint inh">inherits: ${esc(setFmt(s, inh))}</div>`}`;
    } else ctl = control(s, shown, false);
    const isMaster = sec.master === s.key;
    const def = sget(o.defs, path), changed = JSON.stringify(val(path)) !== JSON.stringify(def);
    return `<div class="set-row ${greyed(sec, s) ? "greyed" : ""} ${isMaster ? "master" : ""} ${s.type === "multi" ? "wide" : ""} ${has ? "overridden" : ""}"
        data-text="${esc((s.label + " " + s.help + " " + path + " " + sec.label + " " + (Array.isArray(s.options) ? s.options.map((x) => x.label).join(" ") : "")).toLowerCase())}">
      <div class="set-info"><div class="row" style="gap:6px"><b>${esc(s.label)}</b><span class="badge ap-${s.applies}" title="${esc(ap[1])}">${ap[0]}</span>
        ${has ? `<span class="badge ov-badge">episode</span>` : ""}${!o.project && changed ? `<span class="badge" title="Default: ${esc(setFmt(s, def))}" style="color:var(--gold)">changed</span>` : ""}</div>
