async function SettingsTab(p, el) {
  const url = `/api/projects/${encodeURIComponent(p.slug)}/settings`;
  let sch, cur;
  try { [sch, cur] = await Promise.all([setSchema(), api(url)]); }
  catch (e) { el.innerHTML = `<div class="empty">${esc(e.message)}</div>`; return; }
  const handMade = p.has_edit && p.generator !== "autoplan";
  el.innerHTML = `<div class="card row" style="margin-bottom:12px;gap:12px">
      <div style="flex:1;min-width:260px"><b>Episode overrides</b> <span class="muted" id="ovCount"></span>
        <div class="muted" style="font-size:12px">Everything inherits the global <a href="#/settings">Settings</a>${cur.parent ? ` and the episode <a href="#/project/${encodeURIComponent(cur.parent)}">${esc(cur.parent)}</a>` : ""} unless you override it here.
        <b>render</b> switches apply to the current edit on the next render; <b>plan</b> switches need a re-plan.</div></div>
      <button class="btn" id="ovReplan" title="${handMade ? "Replaces the current HAND-MADE edit.json (a copy is kept in history/)" : "Runs the auto-editor again with these settings"}">↻ Re-plan with these settings</button>
