      <button class="btn small danger" id="ovClear">Clear all overrides</button></div>
    <div class="row" style="margin-bottom:10px"><input type="search" id="ovQ" placeholder="Search settings…" value="${esc(SET_UI.q)}" style="flex:1;min-width:240px"></div>
    <div id="ovBody" class="set-list"></div>`;
  const body = $("#ovBody");
  const draw = () => {
    renderSettings(body, sch, { project: true, eff: cur.effective, inh: cur.inherited, ov: cur.overrides, defs: cur.defaults, onSet, onReset });
