  };
  const save = settingsSaver(url, (r) => { if (r) cur = r; draw(); });
  function onSet(path, value) {
    if (value === null) sdel(cur.overrides, path); else sput(cur.overrides, path, value);
    sput(cur.effective, path, value === null ? sget(cur.inherited, path) : value);
    draw(); save(path, value);
  }
  async function onReset(section) {
    cur = await api(url + "/reset", { method: "POST", body: { section } }); toast("Overrides cleared"); draw();
  }
  const run = async (stage, msg) => {
    try { await api(`/api/projects/${encodeURIComponent(p.slug)}/run/${stage}`, { method: "POST", body: {} }); store.set("tab:" + p.slug, "pipeline"); toast(msg); Project(p.slug); }
    catch (e) { toast(e.message, true); }
  };
  $("#ovQ").oninput = (e) => { SET_UI.q = e.target.value; draw(); };
  $("#ovReplan").onclick = () => {
    if (handMade && !confirm("This episode has a hand-made edit. Re-planning replaces it with a fresh auto-edit (the current edit.json is kept in history/). Continue?")) return;
    run("autoplan", "Re-planning with these settings…");
  };
  $("#ovRender").onclick = () => run("preview", "Rendering preview…");
  $("#ovClear").onclick = async () => { if (confirm("Remove every override for this episode?")) onReset(null); };
  draw();
}

