function setFmt(s, v) {
  if (v == null) return "–";
  if (s.type === "bool") return v ? "on" : "off";
  if (s.type === "multi") return v.length ? `${v.length} switched off` : "all on";
  if (s.type === "select") return s.options.find((o) => o.value === v)?.label ?? v;
