        data-text="${esc((s.label + " " + s.help + " " + path + " " + sec.label + " " + (Array.isArray(s.options) ? s.options.map((x) => x.label).join(" ") : "")).toLowerCase())}">
      <div class="set-info"><div class="row" style="gap:6px"><b>${esc(s.label)}</b><span class="badge ap-${s.applies}" title="${esc(ap[1])}">${ap[0]}</span>
        ${has ? `<span class="badge ov-badge">episode</span>` : ""}${!o.project && changed ? `<span class="badge" title="Default: ${esc(setFmt(s, def))}" style="color:var(--gold)">changed</span>` : ""}</div>
        <div class="set-help">${esc(s.help)}</div><code class="faint" style="font-size:11px">${esc(path)}</code></div>
      <div class="set-ctl">${ctl}</div></div>`;
  };
  el.innerHTML = sch.sections.map((sec) => {
    const master = sec.master ? sec.settings.find((s) => s.key === sec.master) : null;
    const mOn = master ? !!val(`${sec.key}.${sec.master}`) : true;
