    const isOpen = SET_UI.q ? true : open[sec.key] !== false;
    return `<section class="card set-sec ${mOn ? "" : "sec-off"} ${isOpen ? "open" : ""}" data-sec="${sec.key}">
      <div class="set-head" data-toggle="${sec.key}"><span class="set-ico">${esc(sec.icon || "•")}</span>
        <div style="flex:1;min-width:0"><b>${esc(sec.label)}</b> ${master ? `<span class="badge ${mOn ? "r-clean" : "r-explicit"}">${mOn ? "on" : "off"}</span>` : ""}${nOv ? ` <span class="badge ov-badge">${nOv} override${nOv > 1 ? "s" : ""}</span>` : ""}
          <div class="set-help">${esc(sec.help || "")}</div></div>
        ${master && !o.project ? `<label class="switch big" title="${esc(master.label)}" data-stop><input type="checkbox" data-bool="${esc(master.path)}" ${mOn ? "checked" : ""}><span></span></label>` : ""}
        <button class="btn sm" data-reset="${sec.key}" data-stop title="${o.project ? "Remove this section's episode overrides" : "Reset this section to defaults"}">${o.project ? "Clear" : "Reset"}</button>
        <span class="caret">▾</span></div>
      <div class="set-body">${sec.settings.map((s) => row(sec, s)).join("")}</div></section>`;
  }).join("");
  applySettingsSearch(el);

  // events (delegated)
  el.onclick = (e) => {
    const t = e.target.closest("[data-toggle],[data-reset],[data-tri],[data-inherit],[data-custom],[data-chip],[data-allon],[data-alloff]");
    if (!t) return;
