    if (t.dataset.toggle) {
      if (e.target.closest("[data-stop]")) return;
      const k = t.dataset.toggle, sec = t.closest(".set-sec"); sec.classList.toggle("open");
      open[k] = sec.classList.contains("open"); store.set("setOpen", open); return;
    }
    if (t.dataset.tri) return o.onSet(t.dataset.tri, t.dataset.v === "inherit" ? null : t.dataset.v === "on");
    if (t.dataset.inherit) return o.onSet(t.dataset.inherit, null);
    if (t.dataset.custom) { const p = t.dataset.custom; if (!shas(o.ov, p)) o.onSet(p, structuredClone(sget(o.inh, p))); return; }
    const spec = (p) => sch.sections.flatMap((s) => s.settings).find((s) => s.path === p);
    const cur = (p) => [...((o.project ? (shas(o.ov, p) ? sget(o.ov, p) : null) : val(p)) || [])];
    if (t.dataset.chip) {
      if (t.classList.contains("locked")) return toast("Click Custom first to override this list for the episode");
      const p = t.dataset.chip, list = cur(p), v = t.dataset.v, i = list.indexOf(v);
      i >= 0 ? list.splice(i, 1) : list.push(v);
      return o.onSet(p, list);
    }
    if (t.dataset.allon) return o.onSet(t.dataset.allon, []);
    if (t.dataset.alloff) return o.onSet(t.dataset.alloff, spec(t.dataset.alloff).options.map((x) => x.value));
  };
  el.onchange = (e) => {
    const t = e.target;
    if (t.dataset.bool) o.onSet(t.dataset.bool, t.checked);
    else if (t.dataset.num) o.onSet(t.dataset.num, +t.value);
    else if (t.dataset.sel !== undefined) o.onSet(t.dataset.sel, t.value);
  };
  el.oninput = (e) => {
    const t = e.target;
    if (t.dataset.num) { const s = sch.sections.flatMap((x) => x.settings).find((x) => x.path === t.dataset.num); t.nextElementSibling.textContent = setFmt(s, +t.value); }
    if (t.dataset.tq !== undefined) {
      SET_UI.tq[t.dataset.tq] = t.value;
      const pos = t.selectionStart; renderSettings(el, sch, o);
      const n = $(`[data-tq="${CSS.escape(t.dataset.tq)}"]`, el); if (n) { n.focus(); n.setSelectionRange(pos, pos); }
    }
  };
}
function applySettingsSearch(el) {
  const q = SET_UI.q.trim().toLowerCase();
  $$(".set-sec", el).forEach((sec) => {
    let n = 0;
    $$(".set-row", sec).forEach((r) => { const hit = !q || r.dataset.text.includes(q); r.hidden = !hit; n += hit; });
    sec.hidden = !!q && !n;
  });
}

// debounced autosave: collects changes, PATCHes once, toasts
function settingsSaver(url, after) {
  let pending = {}, timer = null;
  return (path, value) => {
    sput(pending, path, value);
    clearTimeout(timer);
    timer = setTimeout(async () => {
      const body = pending; pending = {};
      try { const r = await api(url, { method: "PATCH", body }); toast("✓ Settings saved"); after(r); }
      catch (e) { toast(e.message, true); after(null); }
    }, 350);
  };
}

async function SettingsPage() {
  let sch, cur;
  try { [sch, cur] = await Promise.all([setSchema(true), api("/api/settings")]); }
  catch (e) { view.innerHTML = `<div class="empty">${esc(e.message)}</div>`; return; }
  const nChanged = () => sch.sections.flatMap((s) => s.settings).filter((s) => JSON.stringify(sget(cur.settings, s.path)) !== JSON.stringify(sget(cur.defaults, s.path))).length;
  view.innerHTML = `<div class="row"><div><h1>Settings</h1><p class="sub">Turn any feature of the auto-editor and renderer on or off: all filters or one look, every SFX or one kind, memes, zooms, single motion templates… Changes save automatically. Episodes can override any of these in their own <b>Settings</b> tab.</p></div></div>
    <div class="row set-bar card">
      <input type="search" id="setQ" placeholder="Search settings: filter, zoom, sticker, boss bar…" value="${esc(SET_UI.q)}" style="flex:1;min-width:240px">
      <span class="muted" id="setCount" style="font-size:12px"></span>
      <span class="badge ap-plan" title="${esc(APPLIES.plan[1])}">plan</span><span class="badge ap-render" title="${esc(APPLIES.render[1])}">render</span><span class="badge ap-both" title="${esc(APPLIES.both[1])}">plan + render</span>
      <button class="btn small" id="setExpand">Expand all</button><button class="btn small" id="setCollapse">Collapse all</button>
      <button class="btn small danger" id="setResetAll">Reset all</button></div>
    <div id="setBody" class="set-list"></div>`;
  const body = $("#setBody");
  const draw = () => {
    renderSettings(body, sch, { project: false, eff: cur.settings, defs: cur.defaults, onSet, onReset });
    const n = nChanged(); $("#setCount").textContent = n ? `${n} changed from the defaults` : "all defaults";
  };
  const save = settingsSaver("/api/settings", (r) => { if (r) cur = r; draw(); });
  function onSet(path, value) { sput(cur.settings, path, value ?? sget(cur.defaults, path)); draw(); save(path, value); }
  async function onReset(section) {
    const label = sch.sections.find((s) => s.key === section)?.label;
    if (!confirm(`Reset "${label}" to the defaults?`)) return;
    cur = await api("/api/settings/reset", { method: "POST", body: { section } }); toast(`${label} reset`); draw();
  }
  $("#setQ").oninput = (e) => { SET_UI.q = e.target.value; draw(); };
  $("#setExpand").onclick = () => { store.set("setOpen", {}); draw(); };
  $("#setCollapse").onclick = () => { store.set("setOpen", Object.fromEntries(sch.sections.map((s) => [s.key, false]))); draw(); };
  $("#setResetAll").onclick = async () => {
    if (!confirm("Reset ALL settings to the defaults? (Episode overrides are kept.)")) return;
    cur = await api("/api/settings/reset", { method: "POST", body: {} }); toast("All settings reset"); draw();
  };
  draw();
}

async function SettingsTab(p, el) {
  const url = `/api/projects/${encodeURIComponent(p.slug)}/settings`;
  let sch, cur;
  try { [sch, cur] = await Promise.all([setSchema(), api(url)]); }
  catch (e) { el.innerHTML = `<div class="empty">${esc(e.message)}</div>`; return; }
  const handMade = p.has_edit && p.generator !== "autoplan";
  el.innerHTML = `<div class="card row" style="margin-bottom:12px;gap:12px">
      <div style="flex:1;min-width:260px"><b>Episode overrides</b> <span class="muted" id="ovCount"></span>
        <div class="muted" style="font-size:12px">Everything inherits the global <a href="#/settings">Settings</a>${cur.parent ? ` and the episode <a href="#/project/${encodeURIComponent(cur.parent)}">${esc(cur.parent)}</a>` : ""} unless you override it here.
        <b>render</b> switches apply to the current edit on the next render; <b>plan</b> switches need a re-plan.</div></div>
      <button class="btn" id="ovReplan" title="${handMade ? "Replaces the current HAND-MADE edit.json (a copy is kept in history/)" : "Runs the auto-editor again with these settings"}">↻ Re-plan with these settings</button>
      <button class="btn primary" id="ovRender">▶ Re-render preview</button>
      <button class="btn small danger" id="ovClear">Clear all overrides</button></div>
    <div class="row" style="margin-bottom:10px"><input type="search" id="ovQ" placeholder="Search settings…" value="${esc(SET_UI.q)}" style="flex:1;min-width:240px"></div>
    <div id="ovBody" class="set-list"></div>`;
  const body = $("#ovBody");
  const draw = () => {
    renderSettings(body, sch, { project: true, eff: cur.effective, inh: cur.inherited, ov: cur.overrides, defs: cur.defaults, onSet, onReset });
    const n = Object.values(cur.overrides || {}).reduce((k, s) => k + Object.values(s).filter((v) => v !== null).length, 0);
    $("#ovCount").textContent = n ? `· ${n} override${n > 1 ? "s" : ""}` : "· none (all inherited)";
  };
  const save = settingsSaver(url, (r) => { if (r) cur = r; draw(); });
  function onSet(path, value) {
    if (value === null) sdel(cur.overrides, path); else sput(cur.overrides, path, value);
    sput(cur.effective, path, value === null ? sget(cur.inherited, path) : value);
    draw(); save(path, value);
  }
  async function onReset(section) {
    cur = await api(url + "/reset", { method: "POST", body: { section } }); toast("Overrides cleared"); draw();
  }
  const run = async (stage, msg) => {
    try { await api(`/api/projects/${encodeURIComponent(p.slug)}/run/${stage}`, { method: "POST", body: {} }); store.set("tab:" + p.slug, "pipeline"); toast(msg); Project(p.slug); }
    catch (e) { toast(e.message, true); }
  };
  $("#ovQ").oninput = (e) => { SET_UI.q = e.target.value; draw(); };
  $("#ovReplan").onclick = () => {
    if (handMade && !confirm("This episode has a hand-made edit. Re-planning replaces it with a fresh auto-edit (the current edit.json is kept in history/). Continue?")) return;
    run("autoplan", "Re-planning with these settings…");
  };
  $("#ovRender").onclick = () => run("preview", "Rendering preview…");
  $("#ovClear").onclick = async () => { if (confirm("Remove every override for this episode?")) onReset(null); };
  draw();
}

